namespace Chores.Models;

public class CompletionRecord
{
    public int Id { get; set; }
    public int ChoreId { get; set; }
    public Chore Chore { get; set; } = null!;
    public int CompletedByUserId { get; set; }
    public AppUser CompletedByUser { get; set; } = null!;

    /// <summary>Always stored as UTC.</summary>
    public DateTime CompletedAtUtc { get; set; }

    /// <summary>True when the chore was skipped rather than completed.</summary>
    public bool IsSkipped { get; set; }

    /// <summary>
    /// Identifier generated by the PWA when a completion is recorded offline. Makes replaying a
    /// queued completion idempotent, so a retried sync cannot create a duplicate record.
    /// Null for completions submitted directly from the server-rendered form.
    /// </summary>
    public string? ClientRecordId { get; set; }
}
